// رصد مقياس Interaction to Next Paint (INP) برمجياً
let worstInteractionLatency = 0;
let worstInteractionEntry = null;

const observer = new PerformanceObserver((entryList) => {
  for (const entry of entryList.getEntries()) {
    // التأكد من أن السجل يمثل تفاعلاً حقيقياً للمستخدم
    if (entry.interactionId) {
      const inputDelay = entry.processingStart - entry.startTime;
      const processingDuration = entry.processingEnd - entry.processingStart;
      const presentationDelay = entry.duration - (entry.processingEnd - entry.startTime);

      if (entry.duration > worstInteractionLatency) {
        worstInteractionLatency = entry.duration;
        worstInteractionEntry = entry;

        console.log(`⚡ أسوأ تفاعل حتى الآن: ${entry.name}`);
        console.log(`  إجمالي التأخير: ${entry.duration.toFixed(1)}ms`);
        console.log(`  تأخير الإدخال: ${inputDelay.toFixed(1)}ms`);
        console.log(`  زمن المعالجة: ${processingDuration.toFixed(1)}ms`);
        console.log(`  تأخير الرسم والعرض: ${presentationDelay.toFixed(1)}ms`);
      }
    }
  }
});

// مراقبة أحداث الـ event مع حد أدنى 16ms
observer.observe({
  type: 'event',
  buffered: true,
  durationThreshold: 16,
});

